# Jaws: repeated measures analysis of variance
# Generated from JuliaBUGS.BUGSExamples.VOLUME_2.jaws
using JuliaBUGS

model_def = JuliaBUGS.@bugs("""
model
{
    beta0 ~ dnorm(0.0, 0.001)
    beta1 ~ dnorm(0.0, 0.001)
    for (i in 1:N) {
        Y[i, 1:M] ~ dmnorm(mu[], Omega[ , ])
    }
    for(j in 1:M) {
        mu[j] <- beta0 + beta1* age[j]
    }
    Omega[1 : M , 1 : M] ~ dwish(R[ , ], 4)
    Sigma[1 : M , 1 : M] <- inverse(Omega[ , ])
}
""", false)

build_model(data) = JuliaBUGS.compile(model_def, data)
